Write {"file_path":"D:\code\ESI.ts\examples\universe-post-helpers.ts","content":"/**
 * ESI.ts Example: Universe POST Helpers & Character Affiliation
 *
 * Demonstrates the three safe read-only POST endpoints:
 *  - postBulkNamesToIds (resolve names → IDs)
 *  - postNamesAndCategories (resolve IDs → names + categories)
 *  - postCharacterAffiliation (bulk character corp/alliance lookup)
 *
 * NO AUTHENTICATION REQUIRED — all three endpoints are public.
 *
 * Usage: npm run example:universe-posts
 */
import { EsiClient } from '../src/EsiClient';

const SAMPLE_NAMES = ['Chribba', 'Jita', 'Tritanium', 'Goonswarm Federation', 'CCP Games'];
const SAMPLE_CHARACTER_IDS = [90404873, 90439768, 1689391488];

async function main() {
  const client = new EsiClient();

  try {
    console.log('Universe POST Helpers & Character Affiliation\n');

    // --- Bulk Names → IDs ---
    console.log('Bulk Names → IDs (POST /universe/ids)');
    console.log('-'.repeat(50));
    console.log(`  Looking up: ${SAMPLE_NAMES.join(', ')}`);
    const idResult = await client.universe.postBulkNamesToIds(SAMPLE_NAMES);

    const categories = ['characters', 'systems', 'inventory_types', 'alliances', 'corporations', 'agents', 'constellations', 'factions', 'regions', 'stations'] as const;
    for (const cat of categories) {
      const items = idResult[cat];
      if (items && items.length > 0) {
        console.log(`  ${cat}:`);
        for (const item of items) {
          console.log(`    ${item.name} → ${item.id}`);
        }
      }
    }

    // --- IDs → Names & Categories ---
    console.log('\nIDs → Names & Categories (POST /universe/names)');
    console.log('-'.repeat(50));
    const allIds: number[] = [];
    for (const cat of categories) {
      const items = idResult[cat];
      if (items) {
        for (const item of items) {
          allIds.push(item.id);
        }
      }
    }
    console.log(`  Resolving ${allIds.length} IDs...`);
    const nameResults = await client.universe.postNamesAndCategories(allIds);
    for (const entry of nameResults) {
      console.log(`    ${entry.id}: ${entry.name} (${entry.category})`);
    }

    // --- Character Affiliation ---
    console.log('\nCharacter Affiliation (POST /characters/affiliation)');
    console.log('-'.repeat(50));
    console.log(`  Looking up ${SAMPLE_CHARACTER_IDS.length} characters...`);
    const affiliations = await client.characters.postCharacterAffiliation(SAMPLE_CHARACTER_IDS);
    for (const aff of affiliations) {
      const parts = [`char ${aff.character_id}`, `corp ${aff.corporation_id}`];
      if (aff.alliance_id) parts.push(`alliance ${aff.alliance_id}`);
      if (aff.faction_id) parts.push(`faction ${aff.faction_id}`);
      console.log(`    ${parts.join(' | ')}`);
    }

  } catch (err) {
    console.error('Error:', err instanceof Error ? err.message : err);
    process.exit(1);
  } finally {
    await client.shutdown();
  }
}

main();
"}

Write {"file_path":"D:\code\ESI.ts\examples\freelance-jobs.ts","content":"/**
 * ESI.ts Example: Freelance Jobs
 *
 * Demonstrates the four Equinox freelance job endpoints:
 *  - getCharacterFreelanceJobs (character's posted/accepted jobs)
 *  - getCharacterFreelanceJobParticipation (participation in a specific job)
 *  - getCorporationFreelanceJobs (corporation's posted jobs)
 *  - getCorporationFreelanceJobParticipants (participants in a specific corp job)
 *
 * REQUIRES AUTHENTICATION with scopes:
 *  - esi-characters.read_freelance_jobs.v1
 *  - esi-corporations.read_freelance_jobs.v1
 *
 * Usage: npm run example:freelance-jobs
 */
import { EsiClient } from '../src/EsiClient';
import { EsiError } from '../src/core/util/error';

const CHARACTER_ID = 90439768;
const CORP_ID = 98135622;

async function tryOrSkip<T>(
  label: string,
  fn: () => Promise<T>,
): Promise<T | null> {
  try {
    return await fn();
  } catch (err) {
    if (err instanceof EsiError && [401, 403, 404].includes(err.statusCode ?? 0)) {
      console.log(`  ${label}: endpoint not available — skipped`);
      return null;
    }
    throw err;
  }
}

async function main() {
  const client = new EsiClient();

  try {
    console.log('Freelance Jobs (Equinox)\n');

    // --- Character Freelance Jobs ---
    console.log('Character Freelance Jobs');
    console.log('-'.repeat(50));
    const charJobs = await tryOrSkip('Character jobs', () =>
      client.freelanceJobs.getCharacterFreelanceJobs(CHARACTER_ID),
    );

    if (charJobs) {
      const jobs = charJobs.freelance_jobs;
      console.log(`  Jobs found: ${jobs.length}`);

      for (const job of jobs.slice(0, 5)) {
        console.log(`    ${job.name} (${job.state})`);
        console.log(`      Progress: ${job.progress.current}/${job.progress.desired}`);
        if (job.reward) {
          console.log(`      Reward: ${job.reward.remaining.toLocaleString()} ISK remaining`);
        }
      }
      if (jobs.length > 5) {
        console.log(`    ... and ${jobs.length - 5} more`);
      }

      // If we have jobs, try participation on the first one
      if (jobs.length > 0) {
        const firstJob = jobs[0]!;
        console.log(`\n  Participation in "${firstJob.name}":`);
        const participation = await tryOrSkip('Participation', () =>
          client.freelanceJobs.getCharacterFreelanceJobParticipation(CHARACTER_ID, firstJob.id),
        );
        if (participation) {
          console.log(`    Status: ${participation.status}`);
          console.log(`    Contributions: ${participation.contributions}`);
          if (participation.last_contribution) {
            console.log(`    Last contribution: ${participation.last_contribution}`);
          }
        }
      }
    }

    // --- Corporation Freelance Jobs ---
    console.log('\nCorporation Freelance Jobs');
    console.log('-'.repeat(50));
    const corpJobs = await tryOrSkip('Corporation jobs', () =>
      client.freelanceJobs.getCorporationFreelanceJobs(CORP_ID),
    );

    if (corpJobs) {
      const jobs = corpJobs.freelance_jobs;
      console.log(`  Jobs found: ${jobs.length}`);

      for (const job of jobs.slice(0, 5)) {
        console.log(`    ${job.name} (${job.state})`);
        console.log(`      Progress: ${job.progress.current}/${job.progress.desired}`);
      }
      if (jobs.length > 5) {
        console.log(`    ... and ${jobs.length - 5} more`);
      }

      // If we have jobs, try participants on the first one
      if (jobs.length > 0) {
        const firstJob = jobs[0]!;
        console.log(`\n  Participants in "${firstJob.name}":`);
        const participants = await tryOrSkip('Participants', () =>
          client.freelanceJobs.getCorporationFreelanceJobParticipants(CORP_ID, firstJob.id),
        );
        if (participants) {
          console.log(`    Total participants: ${participants.length}`);
          for (const p of participants.slice(0, 5)) {
            console.log(`      Character ${p.character_id}: ${p.contributions} contributions (${p.status})`);
          }
        }
      }
    }

  } catch (err) {
    console.error('Error:', err instanceof Error ? err.message : err);
    process.exit(1);
  } finally {
    await client.shutdown();
  }
}

main();
"}

Write {"file_path":"D:\code\ESI.ts\examples\write-operations.ts","content":"/**
 * ESI.ts Example: Write Operations (Contacts, Fittings, Mail)
 *
 * Demonstrates create → verify → cleanup for reversible write endpoints:
 *  Contacts: addContacts → editContacts → deleteCharacterContacts
 *  Fittings: createFitting → deleteFitting
 *  Mail:     createMailLabel → deleteMailLabel, sendMail → updateMailMetadata → deleteMail
 *
 * REQUIRES AUTHENTICATION with scopes:
 *  - esi-characters.write_contacts.v1
 *  - esi-fittings.read_fittings.v1
 *  - esi-fittings.write_fittings.v1
 *  - esi-mail.organize_mail.v1
 *  - esi-mail.send_mail.v1
 *  - esi-mail.read_mail.v1
 *
 * Usage: npm run example:write-ops
 */
import { EsiClient } from '../src/EsiClient';
import { EsiError } from '../src/core/util/error';

const CHARACTER_ID = 90439768;
const TEST_CONTACT_ID = 90404873; // Chribba — a well-known character

async function main() {
  const client = new EsiClient();

  try {
    console.log('Write Operations: Contacts, Fittings & Mail\n');

    // ============================================================
    // CONTACTS: add → edit → delete
    // ============================================================
    console.log('Contacts');
    console.log('='.repeat(50));

    // Add contact
    console.log('\n  Adding contact...');
    try {
      const addResult = await client.contacts.postCharacterContacts(CHARACTER_ID, {
        contact_ids: [TEST_CONTACT_ID],
        standing: 5,
      });
      console.log(`    Added: ${JSON.stringify(addResult)}`);

      // Edit contact standing
      console.log('  Editing contact standing...');
      await client.contacts.putCharacterContacts(CHARACTER_ID, {
        contact_ids: [TEST_CONTACT_ID],
        standing: 10,
      });
      console.log('    Updated standing to 10');

      // Delete contact
      console.log('  Deleting contact...');
      await client.contacts.deleteCharacterContacts(CHARACTER_ID, [TEST_CONTACT_ID]);
      console.log('    Deleted successfully');

      console.log('  Contacts lifecycle: PASS');
    } catch (err) {
      if (err instanceof EsiError && err.statusCode === 520) {
        console.log('    Contact already exists or conflict — skipping lifecycle');
      } else if (err instanceof EsiError && [401, 403].includes(err.statusCode ?? 0)) {
        console.log('    Missing scope — skipped');
      } else {
        console.log(`    Error: ${err instanceof Error ? err.message : err}`);
      }
    }

    // ============================================================
    // FITTINGS: create → delete
    // ============================================================
    console.log('\nFittings');
    console.log('='.repeat(50));

    try {
      // Create a test fitting (Rifter with 1x 125mm Gatling AutoCannon)
      console.log('\n  Creating test fitting...');
      const fitting = {
        name: 'ESI.ts Test Fit',
        description: 'Automated test fitting — safe to delete',
        ship_type_id: 587, // Rifter
        items: [
          { type_id: 10190, flag: 'HiSlot0', quantity: 1 }, // 125mm Gatling AutoCannon I
        ],
      };
      const createResult = await client.fittings.createFitting(CHARACTER_ID, fitting);
      const fittingId = createResult.fitting_id;
      console.log(`    Created fitting ID: ${fittingId}`);

      // Delete the fitting
      console.log('  Deleting test fitting...');
      await client.fittings.deleteFitting(CHARACTER_ID, fittingId);
      console.log('    Deleted successfully');

      console.log('  Fittings lifecycle: PASS');
    } catch (err) {
      if (err instanceof EsiError && [401, 403].includes(err.statusCode ?? 0)) {
        console.log('    Missing scope — skipped');
      } else {
        console.log(`    Error: ${err instanceof Error ? err.message : err}`);
      }
    }

    // ============================================================
    // MAIL LABELS: create → delete
    // ============================================================
    console.log('\nMail Labels');
    console.log('='.repeat(50));

    try {
      console.log('\n  Creating test label...');
      const labelId = await client.mail.createMailLabel(CHARACTER_ID, {
        name: 'ESI.ts Test Label',
        color: '#660066',
      });
      console.log(`    Created label ID: ${labelId}`);

      console.log('  Deleting test label...');
      await client.mail.deleteMailLabel(CHARACTER_ID, labelId);
      console.log('    Deleted successfully');

      console.log('  Mail labels lifecycle: PASS');
    } catch (err) {
      if (err instanceof EsiError && [401, 403].includes(err.statusCode ?? 0)) {
        console.log('    Missing scope — skipped');
      } else {
        console.log(`    Error: ${err instanceof Error ? err.message : err}`);
      }
    }

    // ============================================================
    // MAIL: send → update metadata → delete
    // ============================================================
    console.log('\nMail Messages');
    console.log('='.repeat(50));

    try {
      console.log('\n  Sending test mail (to self)...');
      const mailId = await client.mail.sendMail(CHARACTER_ID, {
        recipients: [{ recipient_id: CHARACTER_ID, recipient_type: 'character' }],
        subject: 'ESI.ts Write Test',
        body: 'Automated test mail from ESI.ts — safe to delete.',
      });
      console.log(`    Sent mail ID: ${mailId}`);

      console.log('  Updating mail metadata (marking read)...');
      await client.mail.updateMailMetadata(CHARACTER_ID, mailId, {
        is_read: true,
      });
      console.log('    Marked as read');

      console.log('  Deleting test mail...');
      await client.mail.deleteMail(CHARACTER_ID, mailId);
      console.log('    Deleted successfully');

      console.log('  Mail lifecycle: PASS');
    } catch (err) {
      if (err instanceof EsiError && [401, 403].includes(err.statusCode ?? 0)) {
        console.log('    Missing scope — skipped');
      } else {
        console.log(`    Error: ${err instanceof Error ? err.message : err}`);
      }
    }

    console.log('\n' + '='.repeat(50));
    console.log('All write operation tests complete.');

  } catch (err) {
    console.error('Error:', err instanceof Error ? err.message : err);
    process.exit(1);
  } finally {
    await client.shutdown();
  }
}

main();
"}

